-- Keep the localized warning, but fall back to readable text when the legacy
-- client has not loaded the WOM language bundle yet.
DO $$
DECLARE current_view_oid oid;
DECLARE current_payload text;
DECLARE patched_payload text;
BEGIN
    SELECT view_json
    INTO current_view_oid
    FROM public.runtime_extra_view
    WHERE code = 'WOM_1.0.0_produceTask_processExeLogList';

    IF current_view_oid IS NOT NULL THEN
        current_payload := convert_from(lo_get(current_view_oid), 'UTF8');
        patched_payload := replace(
            current_payload,
            $needle$ReactAPI.international.getText('WOM.custom.randon1585636817654')$needle$,
            $replacement$(function(){var key='WOM.custom.randon1585636817654';var text=ReactAPI.international.getText(key);return !text||text===key?'请选择一条工序执行记录':text;})()$replacement$
        );

        IF patched_payload IS DISTINCT FROM current_payload THEN
            UPDATE public.runtime_extra_view
            SET view_json = lo_from_bytea(0, convert_to(patched_payload, 'UTF8'))
            WHERE code = 'WOM_1.0.0_produceTask_processExeLogList';
        END IF;
    END IF;
END $$;

