)
WHERE code = 'WOM_1.0.0_produceTask_processExeLogList'
  AND position(
      $needle$ReactAPI.international.getText('WOM.custom.randon1585636817654')$needle$
      IN view_json
  ) > 0;

-- The packaged process-execution toolbar uses this key when no row is selected.
-- Seed it explicitly because the recovered runtime otherwise displays the raw key.
WITH seed(i18n_key, i18n_value, langu_code) AS (
    VALUES
        ('WOM.custom.randon1585636817654', '请选择一条工序执行记录', 'zh_CN'),
        ('WOM.custom.randon1585636817654', '請選擇一條工序執行記錄', 'zh_HK'),
        ('WOM.custom.randon1585636817654', 'Please select a process execution record.', 'en_US')
)
UPDATE public.supfusion_i18n_resource existing
SET i18n_value = seed.i18n_value,
    valid = '1',
    modifier = CURRENT_TIMESTAMP,
    modify_time = CURRENT_TIMESTAMP,
    modify_staff_id = 1
FROM seed
WHERE existing.i18n_key = seed.i18n_key
  AND existing.langu_code = seed.langu_code
  AND COALESCE(existing.tenant_id, 'dt') = 'dt'
  AND (
      existing.i18n_value IS NULL
      OR existing.i18n_value = ''
      OR existing.i18n_value = existing.i18n_key
  );

WITH seed(id, i18n_key, i18n_value, langu_code) AS (
    VALUES
        (6579000000228001::bigint, 'WOM.custom.randon1585636817654', '请选择一条工序执行记录', 'zh_CN'),
        (6579000000228002::bigint, 'WOM.custom.randon1585636817654', '請選擇一條工序執行記錄', 'zh_HK'),
        (6579000000228003::bigint, 'WOM.custom.randon1585636817654', 'Please select a process execution record.', 'en_US')
)
INSERT INTO public.supfusion_i18n_resource (
    id, i18n_key, i18n_value, langu_code, module_code, module_version_code, valid,
    tenant_id, creator, create_time, create_staff_id, modifier, modify_time, modify_staff_id
)
SELECT
    seed.id,
    seed.i18n_key,
    seed.i18n_value,
    seed.langu_code,
    'WOM',
    NULL,
    '1',
    'dt',
    'system',
    CURRENT_TIMESTAMP,
    1,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    1
FROM seed
WHERE NOT EXISTS (
    SELECT 1
    FROM public.supfusion_i18n_resource existing
    WHERE existing.i18n_key = seed.i18n_key
      AND existing.langu_code = seed.langu_code
      AND COALESCE(existing.tenant_id, 'dt') = 'dt'
);
